import type { CSSProperties, ReactNode } from 'react';

export type SeasonalEffect =
  | 'leaves'
  | 'rain'
  | 'snow'
  | 'sparkles'
  | 'sakura'
  | 'fireflies'
  | 'none';

export type AudioSegment = {
  start: number;
  end: number;
};

export interface ParticleSettings {
  density?: number;
  speed?: number;
  size?: number;
  opacity?: number;
  direction?: 'up' | 'down' | 'left' | 'right' | 'random';
}

export interface EffectLayer {
  effect: SeasonalEffect;
  particles?: ParticleSettings;
  accent?: string;
}

export interface SeasonalThemeBackground {
  type?: 'solid' | 'gradient';
  solidColor?: string;
  gradient?: string;
  gradientDirection?: string;
  gradientColors?: string[];
  fallbackColor?: string;
  videoUrl?: string;
}

export interface SeasonalThemeColors {
  primaryAccent?: string;
  secondaryAccent?: string;
  particleColor?: string;
  textColor?: string;
  controlBackground?: string;
  controlText?: string;
  controlBorder?: string;
}

export interface SeasonalThemeTypography {
  fontFamily?: string;
  headingSize?: string;
  bodySize?: string;
  fontWeight?: string | number;
}

export interface SeasonalTheme {
  id?: string;
  label?: string;
  background?: SeasonalThemeBackground;
  colors?: SeasonalThemeColors;
  typography?: SeasonalThemeTypography;
  effects?: EffectLayer[];
  disableParticles?: boolean;
}

export type SeasonDefinition = {
  id: string;
  label: string;
  description: string;
  videoSrc?: string;
  audioSrc?: string;
  audioSegment?: AudioSegment;
  effect?: SeasonalEffect;
  accent?: string;
  background?: string;
  symbol?: ReactNode;
  particles?: ParticleSettings;
  theme?: SeasonalTheme;
  effects?: EffectLayer[];
};

export type SeasonalLoungeProps = {
  seasons: SeasonDefinition[];
  initialSeasonId?: string;
  className?: string;
  volume?: number;
  allowFullscreen?: boolean;
  showAudioControl?: boolean;
  showSeasonPicker?: boolean;
  calmModeLabel?: string;
  onSeasonChange?: (season: SeasonDefinition) => void;
  style?: CSSProperties;
  theme?: SeasonalTheme;
};

export type SeasonalOverlayProps = {
  effect: SeasonalEffect;
  accent?: string;
  count?: number;
  className?: string;
  settings?: ParticleSettings;
  particles?: ParticleSettings;
};

.seasonal-lounge {
  --seasonal-accent: #f9a8d4;
  --seasonal-accent-secondary: #f472b6;
  --seasonal-text: white;
  --seasonal-control-bg: rgba(0, 0, 0, 0.36);
  --seasonal-control-color: white;
  --seasonal-control-border: rgba(255, 255, 255, 0.2);
  --seasonal-font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  --seasonal-heading-size: clamp(2rem, 6vw, 4rem);
  --seasonal-body-size: 0.95rem;

  position: relative;
  isolation: isolate;
  display: flex;
  min-height: 32rem;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 1.75rem;
  background: #24141f;
  color: var(--seasonal-text);
  font-family: var(--seasonal-font-family);
}

.seasonal-lounge--calm,
.seasonal-lounge:fullscreen {
  position: fixed;
  inset: 0;
  z-index: 9999;
  width: 100vw;
  height: 100dvh;
  min-height: 100dvh;
  border: 0;
  border-radius: 0;
  background: #080608;
}

.seasonal-lounge__video,
.seasonal-lounge__shade,
.seasonal-lounge__particles {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.seasonal-lounge__video {
  z-index: -3;
  object-fit: cover;
}

.seasonal-lounge--calm .seasonal-lounge__video,
.seasonal-lounge:fullscreen .seasonal-lounge__video {
  object-fit: contain;
}

.seasonal-lounge__shade {
  z-index: -1;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.9), rgba(0, 0, 0, 0.24) 65%, rgba(0, 0, 0, 0.08));
}

.seasonal-lounge__topbar {
  position: absolute;
  top: 1rem;
  right: 1rem;
  z-index: 4;
  display: flex;
  gap: 0.5rem;
}

.seasonal-lounge__control,
