.seasonal-lounge__particle {
  position: absolute;
  top: -12%;
  left: var(--particle-left);
  width: var(--particle-size);
  height: var(--particle-size);
  opacity: 0;
  will-change: transform, opacity;
  animation-delay: var(--particle-delay);
  animation-duration: var(--particle-duration);
  animation-iteration-count: infinite;
  animation-timing-function: linear;
}

.seasonal-lounge__particle--leaves,
.seasonal-lounge__particle--sakura {
  width: auto;
  height: auto;
  font-size: var(--particle-size);
  filter: drop-shadow(0 4px 5px rgba(0, 0, 0, 0.25));
  animation-name: seasonal-fall;
}

.seasonal-lounge__particle--rain {
  width: 1px;
  height: calc(var(--particle-size) * 4.5);
  border-radius: 999px;
  background: linear-gradient(transparent, color-mix(in srgb, var(--seasonal-accent), white 24%));
  animation-name: seasonal-rain;
}

.seasonal-lounge__particle--snow {
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.84);
  box-shadow: 0 0 9px rgba(224, 242, 254, 0.7);
  animation-name: seasonal-snow;
}

.seasonal-lounge__particle--fireflies {
  width: calc(var(--particle-size) * 0.35);
  height: calc(var(--particle-size) * 0.35);
  border-radius: 50%;
  background: var(--seasonal-accent);
  box-shadow: 0 0 12px 3px color-mix(in srgb, var(--seasonal-accent), transparent 55%);
  animation-name: seasonal-firefly;
}

.seasonal-lounge__particle--sparkles {
  top: var(--particle-top);
  left: -12%;
  width: auto;
  height: auto;
  color: var(--seasonal-accent);
  font-size: calc(var(--particle-size) * 1.15);
  animation-name: seasonal-breeze;
  animation-timing-function: ease-in-out;
}

@keyframes seasonal-fall {
  0% { opacity: 0; transform: translate3d(0, -8vh, 0) rotate(0deg) scale(0.7); }
  10% { opacity: 0.88; }
  45% { transform: translate3d(calc(var(--particle-drift) * -0.35), 45vh, 0) rotate(160deg) scale(1); }
  100% { opacity: 0.12; transform: translate3d(var(--particle-drift), 112vh, 0) rotate(460deg) scale(0.75); }
}

@keyframes seasonal-rain {
  0% { opacity: 0; transform: translate3d(0, -14vh, 0) rotate(8deg); }
  12% { opacity: 0.7; }
  100% { opacity: 0; transform: translate3d(-55px, 116vh, 0) rotate(8deg); }
}

@keyframes seasonal-snow {
  0% { opacity: 0; transform: translate3d(0, -10vh, 0) scale(0.55); }
  12% { opacity: 0.8; }
  100% { opacity: 0.1; transform: translate3d(var(--particle-drift), 110vh, 0) scale(1); }
}

@keyframes seasonal-firefly {
  0%, 100% { opacity: 0.08; transform: translate3d(0, 88vh, 0) scale(0.7); }
  35% { opacity: 0.9; transform: translate3d(var(--particle-drift), 52vh, 0) scale(1.15); }
  70% { opacity: 0.28; transform: translate3d(calc(var(--particle-drift) * -0.4), 25vh, 0) scale(0.8); }
}

@keyframes seasonal-breeze {
  0% { opacity: 0; transform: translate3d(-8vw, 18px, 0) rotate(0deg) scale(0.7); }
  14% { opacity: 0.78; }
  50% { opacity: 0.5; transform: translate3d(54vw, -22px, 0) rotate(170deg) scale(1); }
  100% { opacity: 0; transform: translate3d(124vw, -12px, 0) rotate(360deg) scale(0.55); }
}

@media (prefers-reduced-motion: reduce) {
  .seasonal-lounge__particle {
    display: none;
